rows[99261]={title={{15,989552364},"고문의 파도"},description={"^when a shard of torment is unable to focus its energy on a nearby target, it unleashes that energy in a violent wave, dealing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to all enemies%.$","고문의 파편이 주위에 기운을 집중시킬 대상이 없으면, 그 기운을 난폭한 파도로 발산하여 모든 플레이어에게 \0311\031의 암흑 피해를 입힙니다.",{0},{1}}}
rows[99262]={title={{11,512864368},"생기의 불꽃"},description={"^a fiery energy builds within you as you come to the aid of your tormented allies%. casting a single%-target direct heal on a target affected by blaze of glory will increase healing done on such targets by ([%+%-]?%d[%d,.%+%-to –]*)%% per stack of vital spark, lasting for ([%+%-]?%d[%d,.]* %a+)%.$","고문당한 아군을 도울 때 불같은 기운이 내면에 쌓입니다. 영광의 빛의 영향을 받는 대상에게 단일 대상 치료 주문을 시전하면 \0312\031 동안 중첩된 생기의 불꽃 하나마다 치유량이 \0311\031%씩 증가합니다.",{0,1},{1,2}},aura={"^casting a single%-target direct heal on a target affected by blaze of glory will increase healing done on such targets by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","영광의 빛의 영향을 받는 대상에게 단일 대상 치료 주문을 시전하면 \0312\031 동안 대상이 받는 치유 효과 \0311\031%만큼 증가",{0,1},{1,2}}}
rows[99263]={title={{11,970339664},"생기의 불길"},description={"^a powerful healing flame has awakened within you, greatly increasing healing done to targets affected by blaze of glory for ([%+%-]?%d[%d,.]* %a+)%.$","내면에 강력한 치유의 불길이 일어나 \0311\031 동안 영광의 빛 효과를 받는 대상을 치유할 때 치유량이 크게 증가합니다.",{1},{1}},aura={"^healing done to targets affected by blaze of glory increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","영광의 빛 효과를 받는 대상을 치유할 때 치유량 \0311\031%만큼 증가",{0},{1}}}
