rows[100797]={title={{13,1253361024},"불 고문"},description={"^the caster is enveloped in swirling flames, lashing out every ([%+%-]?%d[%d,.%+%-to –]*) sec to deal ([%+%-]?%d[%d,.%+%-to –]*) fire damage to the nearest target and increasing their fire damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","시전자가 소용돌이치는 화염에 휩싸여 \0311\031초마다 무기를 크게 휘둘러 가장 가까운 대상에게 \0312\031의 화염 피해를 입히고 \0314\031 동안 대상이 받는 화염 피해를 \0313\031%만큼 증가시킵니다.",{0,0,0,1},{1,2,3,4}},aura={"^lashes out every ([%+%-]?%d[%d,.%+%-to –]*) sec, dealing ([%+%-]?%d[%d,.%+%-to –]*) fire damage to the nearest target and increasing their fire damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031초마다 무기를 크게 휘둘러 가장 가까운 대상에게 \0312\031의 화염 피해를 입히고 \0314\031 동안 대상이 받는 화염 피해를 \0313\031%만큼 증가시킴",{0,0,0,1},{1,2,3,4}}}
