rows[102996]={title={{11,1356317},"그림자 관통"},description={"^increases shadow damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. stacks%.$","\0312\031 동안 받는 암흑 피해가 \0311\031%만큼 증가합니다. 효과가 중첩됩니다.",{0,1},{1,2}},aura={"^increases shadow damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","받는 암흑 피해 \0311\031%만큼 증가",{0},{1}}}
