rows[103558]={title={{18,598264877},"숨막히는 연막탄"},description={"^creates a cloud of thick smoke in an ([%+%-]?%d[%d,.%+%-to –]*) yard radius around the caster for ([%+%-]?%d[%d,.]* %a+)%. enemies are unable to target into or out of the smoke cloud and will take ([%+%-]?%d[%d,.%+%-to –]*) nature damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","시전자로부터 반경 \0311\031미터 지역에 \0312\031 동안 짙은 연기 구름을 피웁니다. 플레이어는 연기 속에서 연기 밖, 또는 연기 밖에서 연기 속 대상을 상대로 행동을 취할 수 없으며 \0314\031초마다 \0313\031의 자연 피해를 입습니다.",{0,1,0,0},{1,2,3,4}},aura={"^a smoke cloud interferes with targeting%. ([%+%-]?%d[%d,.%+%-to –]*) nature damage inflicted every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","연막이 대상을 향한 행동 방해\010\0312\031초마다 \0311\031의 자연 피해",{0,0},{1,2}}}
