rows[105652]={title={{14,150692383},"황혼의 불길"},description={{157,719240938},"암흑의 불길을 광범위로 내뿜어 고룡쉼터 사원 꼭대기에서 움직임을 제한합니다. 효과가 취소되거나 차단되기 전까지 지속됩니다."},aura={"^channeling shadow flame over a large area atop wyrmrest temple%. victims within the area of effect will take ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds they are caught within the affected area%. interrupting this ability will prevent this drake from further use of this ability%.$","고룡쉼터 사원 꼭대기에 암흑의 불길을 광범위로 내뿜습니다. 범위 안의 적은 \0312\031초마다 \0311\031의 암흑 피해를 입습니다. 이 기술을 차단당한 비룡은 이 기술을 다시 사용할 수 없습니다.",{0,0},{1,2}}}
