rows[106371]={title={{16,1703153513},"황혼의 시간"},description={"^the hour of twilight falls upon ultraxion's foes%. enemies caught within the twilight realm take ([%+%-]?%d[%d,.%+%-to –]*) unresistable shadow damage%. enemies within the normal realm are instantly pulled back into the twilight realm%. if no enemies are hit by hour of twilight, the aspects will take the full brunt of the attack, disrupting the shield protecting the dragon soul and heralding the end of all life on azeroth%.$","울트락시온의 적에게 황혼의 시간이 내립니다. 황혼 세계에 사로잡힌 대상은 \0311\031의 저항할 수 없는 암흑 피해를 입습니다. 현실 세계에 있는 대상은 즉시 황혼 세계로 끌려들어갑니다. 만약 아무도 황혼의 시간을 맞지 않으면, 위상들이 대신 피해를 받고 용의 영혼을 감싼 보호막이 흐트러져 아제로스의 모든 생명이 종말을 맞이하게 됩니다.",{0},{1}}}
rows[106372]={title={{20,990775352},"불안정한 괴수"},description={"^growing twilight instability causes arcs of twilight energy to erupt from ultraxion's hide every ([%+%-]?%d[%d,.%+%-to –]*) seconds%. instability prevents ultraxion from parrying attacks%.$","황혼의 불안정성이 점점 자라나 \0311\031초마다 울트락시온의 피부에서 황혼 에너지를 방출합니다. 불안정성 때문에 울트락시온은 공격을 막아낼 수 없습니다.",{0},{1}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%., split evenly amongst enemy players within ([%+%-]?%d[%d,.%+%-to –]*) yards of the target%. unable to parry%.$","\0313\031미터 반경 안에 있는 적 플레이어에게 \0312\031초마다 \0311\031의 암흑 피해를 고루 분배\010공격을 막을 수 없음",{0,0,0},{1,2,3}}}
rows[106373]={title={{19,1142333307},"자라나는 불안정성"},description={"^growing twilight instability causes arcs of twilight energy to erupt from ultraxion's hide at an increased rate%. reduces the time between casts of twilight instability by ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","황혼의 불안정성이 점점 자라나 울트락시온의 피부에서 황혼 에너지를 분출하는 빈도가 증가합니다. 황혼의 불안정성을 시전하는 간격이 \0311\031초만큼 감소합니다.",{0},{1}}}
rows[106374]={title={{20,977168149},"황혼의 불안정성"}}
