rows[106395]={title={{19,519526853},"최고조의 불안정성"},description={"^ultraxion's instability is reaching critical levels%. allows ultraxion to cast hour of twilight significantly more often%. if ultraxion is not defeated within ([%+%-]?%d[%d,.%+%-to –]*) seconds, a massive twilight eruption will decimate all nearby life%.$","울트락시온의 불안정성이 한계에 다다랐습니다. 황혼의 시간을 시전하는 빈도가 눈에 띄게 늘어납니다. \0311\031초 안에 울트락시온을 쓰러트리지 못하면 대규모 황혼 분출이 일어나 주변의 모든 생명체를 제거합니다.",{0},{1}}}
